def transform(grid):
    h, w = len(grid), len(grid[0])
    oh, ow = 2*h, 2*w
    result = [[0]*ow for _ in range(oh)]

    # Copy input at each quadrant

    # Top-left: original
    for r in range(h):
        for c in range(w):
            result[r][c] = grid[r][c]

    # Top-right: 90° clockwise
    for r in range(h):
        for c in range(w):
            result[r][c + w] = grid[w - 1 - c][r]

    # Bottom-left: 270° clockwise (90° counter-clockwise)
    for r in range(h):
        for c in range(w):
            result[r + h][c] = grid[c][h - 1 - r]

    # Bottom-right: 180°
    for r in range(h):
        for c in range(w):
            result[r + h][c + w] = grid[h - 1 - r][w - 1 - c]

    return result
